// Builds the canonical book record from the flattened item.
// One code path for both ingest entry points.
const item = $input.first().json;

const slugify = (s) =>
  String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);

const num = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const str = (v) => (v === undefined || v === null || v === '' ? null : String(v));

// tags: accept an array, a JSON array string, or a comma/semicolon separated string.
const tags = (() => {
  const raw = item.tags;
  if (Array.isArray(raw)) return raw.map((t) => String(t).trim()).filter(Boolean);
  if (typeof raw === 'string' && raw.trim().startsWith('[')) {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map((t) => String(t).trim()).filter(Boolean);
    } catch (e) {
      // fall through to the delimiter split below
    }
  }
  return String(raw || '')
    .split(/[,;]/)
    .map((t) => t.trim())
    .filter(Boolean);
})();

const title = str(item.title) || 'Untitled';
const author = str(item.author);
const genre = str(item.genre);
const description = str(item.description) || '';
const content = str(item.content) || '';

// The whole book text as indexed. Title/author/genre are prepended on purpose:
// it keeps a book findable by name even when only its description was supplied.
const text = [title, author ? 'by ' + author : '', genre ? '[' + genre + ']' : '']
  .filter(Boolean)
  .join(' ')
  .concat('. ', description, content ? ' ' + content : '')
  .trim();

const book_id = str(item.book_uuid) || slugify(author ? author + ' ' + title : title) || 'book-' + Date.now();

return [{
  json: {
    book_id,
    title,
    author,
    genre,
    tags,
    description,
    content,
    text,
    published_year: num(item.published_year),
    page_count: num(item.page_count),
    rating: num(item.rating),
    language: str(item.language) || 'en',
    book_url: str(item.book_url),
    source: str(item.upstream) || 'ingest',
  },
}];
